/* Agent shops design preview. Tab-memory fixtures only; never registers in the live API application. */
(function () {
  const requestedPage = location.hash.slice(1);
  document.addEventListener('DOMContentLoaded', () => {
    if (window.PS) return; // The backend handoff will implement these features separately.
    const S = window.ShopUI = {
      lists: [
        {id:'eu',name:'Austria',currency:'EUR',region:'Austria',prices:products.map(p=>Math.round(p.price*100))},
        {id:'de',name:'Germany',currency:'EUR',region:'Germany',prices:products.map(p=>Math.round((p.price+5)*100))},
        {id:'ae',name:'Dubai',currency:'AED',region:'United Arab Emirates',prices:products.map(p=>Math.round(p.price*4*100))}
      ], assigned:agents.map((_,i)=>i===1?'de':'eu'), profiles:agents.map((a,i)=>({name:a.short+'’s stock',slug:'shop-'+(i+1),pin:'2468',active:true,showQty:false,epoch:1})),
      priceDrafts:{}, checkoutDraft:{}, list:'eu', listSearch:'', shopSearch:'', category:'all', cart:{}, unlocked:new Map(), publicAccount:Number(new URLSearchParams(location.search).get('shopAccount')||0),
      requests:[], selected:null, filter:'all', query:'', next:103, last:null, customers:[], chat:null, visible:20, chatQuery:'', messageDrafts:new Map(), emailHistory:[], customerContact:null, attachment:null
    };
    const newRoutes = new Set(['price-lists','price-list','my-shop','customer-requests','customer-request','customers','customer-chat','shop','checkout','shop-confirmation','shop-chat']);
    const publicRoutes = new Set(['shop','checkout','shop-confirmation','shop-chat']);
    const money=(c,currency='EUR')=>new Intl.NumberFormat('en-IE',{style:'currency',currency,minimumFractionDigits:2,maximumFractionDigits:2}).format(c/100);
    const activeAccount=()=>progressIndex();
    const profile=(i=activeAccount())=>S.profiles[i];
    const listFor=i=>S.lists.find(l=>l.id===S.assigned[i]);
    const control=(text,ico,action,cls='')=>btn(text,ico,`data-shop-action="${action}"`,cls);
    const ib=(ico,action,label)=>`<button type="button" class="icon-btn" data-shop-action="${action}" aria-label="${esc(label)}" title="${esc(label)}">${icon(ico)}</button>`;
    const field=(label,id,content)=>`<div class="field"><label for="${id}">${label}</label>${content}</div>`;
    const input=(id,value='',attrs='')=>`<input id="${id}" value="${esc(value)}" ${attrs}>`;
    const note=(text,ico='info')=>`<div class="su-note">${icon(ico)}<span>${text}</span></div>`;
    const empty=(text)=>`<div class="su-empty">${icon('inbox')}<p>${text}</p></div>`;
    const person=(name)=>`<span class="avatar purple">${esc(name.split(/\s+/).map(x=>x[0]).slice(0,2).join(''))}</span>`;
    const currentRequest=()=>S.requests.find(r=>r.id===S.selected);
    const canManage=()=>state.role==='agent'&&!workflow.support;
    const shopURL=i=>{const u=new URL(location.href);u.search='?view=agent&shopAccount='+i;u.hash='shop';return u.href;};
    const cents=v=>{const t=String(v).trim();return /^\d{1,7}(\.\d{1,2})?$/.test(t)?Math.round(Number(t)*100):null;};
    function queryStock(i){return progressStock(i).filter(p=>p.qty>0&&!p.catalogueArchived);}
    function quote(lines,i){
      const counts={};for(const l of lines){if(!Number.isSafeInteger(l.q)||l.q<1||l.q>999||!products[l.product])return null;counts[l.product]=(counts[l.product]||0)+l.q;}
      const allocations={};for(const [id,q] of Object.entries(counts)){const rows=priceQuote(i,+id,q);if(!rows)return null;allocations[id]=rows.map(r=>({...r,left:r.q}));}
      const rows=[];for(const [lineIndex,l] of lines.entries()){let left=l.q;for(const a of allocations[l.product]){const n=Math.min(left,a.left);if(n){const original=Math.round(a.price*100),discount=l.kind==='gift'?original:l.kind==='discount'?l.discount||0:0;if(discount>original)return null;rows.push({...a,lineIndex,q:n,product:l.product,originalCents:original,priceCents:original-discount,kind:l.kind||'normal',reason:l.reason||''});a.left-=n;left-=n;}if(!left)break;}}
      const com=saleCommissionAllocations(rows.map(r=>({...r,price:r.priceCents/100})),i);
      return {rows:rows.map((r,j)=>({...r,commission:com[j]})),units:rows.reduce((n,r)=>n+r.q,0),total:rows.reduce((n,r)=>n+r.priceCents*r.q,0),cost:rows.reduce((n,r)=>n+Math.round(r.cost*100)*r.q,0),commission:com.reduce((n,v)=>n+v,0)};
    }
    const lineSummary=(r)=>{const q=quote(r.lines,r.account);return q?{...q,remit:q.total-q.commission}:null;};
    const statusColor=s=>s==='Converted'?'green':['Declined','Cancelled','Expired'].includes(s)?'orange':s==='New'?'purple':'blue';
    function createThread(account,name,email,initial){
      const c={id:'client-'+S.customers.length,account,name,email,messages:[{by:'customer',text:initial,at:'10:24'}],unread:1};S.customers.unshift(c);return c;
    }
    function seed(){
      S.requests=[{id:'CR-0102',account:0,name:'Lena Hoffmann',email:'lena@example.test',phone:'+43 660 123 4567',address:'Example address · Vienna, Austria',delivery:'Delivery',payment:'Revolut',status:'New',date:reportingToday,note:'Please let me know when collection is possible.',lines:[{product:0,q:2},{product:4,q:1}]},{id:'CR-0101',account:0,name:'Noah Weber',email:'noah@example.test',phone:'+43 660 555 0101',address:'Pickup with agent',delivery:'Pickup',payment:'Cash',status:'Awaiting payment',date:reportingToday,note:'I will pay when I collect.',lines:[{product:2,q:1}]}];
      S.requests.forEach(r=>{r.originalTotal=lineSummary(r)?.total;const c=createThread(r.account,r.name,r.email,r.note);r.chatId=c.id;});
      const names=['Emma Fischer','Oliver Klein','Mia Wagner','Leo Huber','Sofia Bauer','Elias Schmid','Hannah Gruber','Felix Mayer','Clara Wolf','Jonas Braun','Lina Hofer','Paul Richter','Anna Berger','Max Fuchs','Laura Weber','Ben Hartmann','Lea Zimmer','Lukas Lang','Ella Maier','Finn Koch','Marie Schwarz','Theo Brandt'];
      names.forEach((name,j)=>S.customers.push({id:'sample-'+j,account:0,name,email:'customer'+j+'@example.test',unread:0,messages:[{by:'customer',text:j%2?'Thank you for your help.':'Could you share the document for my order?',at:'Yesterday'}]}));
      createThread(1,'Alex Winter','alex@example.test','Could I arrange pickup?');
    }
    seed();
    const priorIndex=progressIndex;progressIndex=function(){return state.role==='agent'&&S.workspaceAccount!==undefined&&!workflow.support?S.workspaceAccount:priorIndex();};
    const priorRender=render,priorNav=workflowNav,priorModal=openModal,priorAgent=adminAgentDetail,priorOrder=orderDetailPage,priorDesk=orderDeskPage;
    navAdmin.splice(navAdmin.findIndex(n=>n[0]==='catalogue')+1,0,['price-lists','tags','Price lists']);
    workflowNav=function(){const nav=priorNav();nav.splice(nav.findIndex(n=>n[0]==='stock')+1,0,['my-shop','store','My shop']);return nav;};
    Object.assign(titles,{'price-lists':'Price lists','price-list':'Price list','my-shop':'My shop','customer-requests':'Orders','customer-request':'Customer request',customers:'Customers','customer-chat':'Customer chat'});
    adminAgentDetail=function(){return priorAgent()+`<section class="panel mt"><div class="panel-head"><h2>Regional prices</h2>${control('Assign list','pencil','assign:'+state.agent,'small')}</div><div class="panel-body"><strong>${esc(listFor(state.agent)?.name||'Not assigned')}</strong><p class="muted">${esc(listFor(state.agent)?.currency||'')} · future stock defaults</p>${note('Received stock keeps its saved batch prices.')}${control('Preview new stock prices','package-plus','region-preview:'+state.agent,'mt')}</div></section>`;};
    orderDeskPage=function(){return (state.role==='agent'?inboxTabs('orders'):'')+priorDesk();};
    orderDetailPage=function(){const d=orderDesk.detail,o=d&&orderRecord(d.index,d.id);return priorOrder()+(o?`<section class="panel mt su-order-protocol"><div class="panel-head"><h2>Protocols</h2>${icon('files')}</div><div class="panel-body"><div class="su-inline-actions">${control('Email protocols','mail','protocol:'+o.key,'primary')}${control('Share PDFs','share-2','share:'+o.key)}</div><div class="su-helper">Approved PDFs for the items in this order.</div></div></section>`:'');};
    openModal=function(title,body,wide){priorModal(title,body,wide);const form=$('#setup-account-form');if(form&&!$('#su-setup-list')){const idx=form.dataset.editing==='true'?Number(form.dataset.account):null;const el=document.createElement('div');el.className='form-grid setup-section su-setup-region';el.innerHTML=field('Regional price list','su-setup-list',`<select id="su-setup-list">${S.lists.filter(l=>!l.archived).map(l=>`<option value="${l.id}" ${l.id===(idx===null?'eu':S.assigned[idx])?'selected':''}>${esc(l.name)} · ${l.currency}</option>`).join('')}</select>`)+`<p class="su-helper">Default prices for new stock. Existing batches stay unchanged.</p>`;form.querySelector('.form-actions').before(el);}};
    document.addEventListener('submit',e=>{if(e.target.id==='setup-account-form'){const form=e.target,sel=$('#su-setup-list');if(form.dataset.editing==='true'&&sel&&form.checkValidity())S.assigned[Number(form.dataset.account)]=sel.value;}},true);
    render=function(){
      document.body.classList.toggle('su-public',publicRoutes.has(state.page));document.body.classList.toggle('su-conversation',state.page==='customer-chat'||(state.page==='shop-chat'&&!!S.customerContact));document.body.classList.toggle('su-page',newRoutes.has(state.page));
      if(!newRoutes.has(state.page)){priorRender();enhanceMessages();return;}
      closeMobileNavigation();messageLayoutReset();stopLoginWater();messageStopRecording(true);dismissMeasureHelp();
      document.documentElement.dataset.theme=state.theme;document.body.classList.toggle('collapsed',state.collapsed);
      if(publicRoutes.has(state.page)){renderPublic();return;}
      if((['price-lists','price-list'].includes(state.page)&&state.role!=='admin')||(!['price-lists','price-list'].includes(state.page)&&state.role!=='agent')){go(state.role==='admin'?'agents':'my-shop');return;}
      $('#preview-toolbar').innerHTML=previewToolbar();$('#app').innerHTML=shell();document.title=(titles[state.page]||'PeptiStock')+' · PeptiStock';
      const views={'price-lists':priceLists,'price-list':priceList,'my-shop':myShop,'customer-requests':requestList,'customer-request':requestDetail,customers:customerList,'customer-chat':customerChat};
      $('#view').innerHTML=views[state.page]();icons();motionMount();mountChat();mountMore();
    };
    function inboxTabs(active){const count=S.requests.filter(r=>r.account===activeAccount()&&r.status==='New').length;return `<div class="su-tabs su-order-tabs" role="group" aria-label="Orders and customer requests"><button type="button" data-page="sales" ${active==='orders'?'class="active" aria-current="page"':''}>Orders</button><button type="button" data-page="customer-requests" ${active==='requests'?'class="active" aria-current="page"':''}>Requests${count?`<span class="su-order-count" aria-label="${count} new customer requests">${count>99?'99+':count}</span>`:''}</button></div>`;}
    function enhanceMessages(){if(state.role!=='agent'||state.page!=='messages')return;const el=document.createElement('div');el.className='su-message-tabs';el.innerHTML=`<button class="active">Admin</button><button data-page="customers">Customers ${badge(S.customers.filter(c=>c.account===activeAccount()&&c.unread).length)}</button>`;$('#view')?.prepend(el);}
    function priceLists(){return `<div class="su-heading"><div><h1>Regional price lists</h1><p>One catalogue. Prices for every market.</p></div>${control('Create list','plus','new-list','primary')}</div><div class="su-list-grid">${S.lists.map(l=>`<article class="panel su-list-card"><div class="su-inline"><span class="su-glyph">${icon('globe-2')}</span><span class="badge">${l.currency}</span>${l.archived?badge('Archived','orange'):''}</div><h2>${esc(l.name)}</h2><p class="muted">${esc(l.region)}</p><div class="su-list-meta"><span>${l.prices.length} variants</span><span>${S.assigned.filter(id=>id===l.id).length} ${S.assigned.filter(id=>id===l.id).length===1?'account':'accounts'}</span></div><div class="su-inline-actions">${control('Open list','arrow-up-right','list:'+l.id,'primary')}${control('Duplicate','copy','duplicate:'+l.id,'')}</div></article>`).join('')}</div>${note('Lists set defaults for new shipments. Received stock and recorded orders keep their saved prices.','layers')}`;}
    function priceList(){const l=S.lists.find(l=>l.id===S.list)||S.lists[0];return `<div class="su-heading">${control('Price lists','arrow-left','lists')}<div class="su-inline-actions">${control('Rename','pencil','rename:'+l.id)}${control(l.archived?'Restore':'Archive','archive','archive:'+l.id)}</div></div><section class="panel"><div class="panel-head"><div><h1>${esc(l.name)}</h1><small>${l.currency} · ${esc(l.region)}</small></div>${badge('Future stock')}</div><div class="su-price-top"><div class="search">${icon('search')}<input id="su-list-search" type="search" placeholder="Search products…" value="${esc(S.listSearch)}" aria-label="Search price list"></div>${control('Save prices','check','save-prices','primary')}</div><div class="su-price-head"><span>Product</span><span>Selling price / unit</span></div><div id="su-price-rows">${products.filter(p=>(p.name+' '+p.dose).toLowerCase().includes(S.listSearch.toLowerCase())).map(p=>`<div class="su-price-row">${productGlyph(p)}<div class="grow"><strong>${esc(p.name)}</strong><small>${esc(p.dose)}</small></div><label class="su-price-input"><span>${l.currency}</span><input type="number" min="0.01" max="1000000" step="0.01" inputmode="decimal" aria-label="${esc(p.name+' '+p.dose+' price')}" data-list-price="${p.id}" value="${esc(S.priceDrafts[l.id]?.[p.id]??(l.prices[p.id]/100).toFixed(2))}" ${l.archived?'disabled':''}></label></div>`).join('')}</div></section>${note('Changes do not reprice existing batches. Landed costs stay separate from customer selling prices.')}`;}
    function listModal(id=null,duplicate=false){const l=S.lists.find(x=>x.id===id);openModal(duplicate?'Duplicate price list':id?'Edit list details':'Create price list',`<form id="su-list-form" data-list="${id||''}" data-duplicate="${duplicate}"><div class="form-grid">${field('List name','su-list-name',input('su-list-name',duplicate?l.name+' copy':l?.name||'','required maxlength="60" placeholder="e.g. Dubai retail"'))}${field('Region','su-list-region',input('su-list-region',l?.region||'','required maxlength="80" placeholder="Country or market"'))}${field('Currency','su-list-currency',`<select id="su-list-currency" ${id&&!duplicate?'disabled':''}>${['EUR','AED','USD','GBP','CHF'].map(c=>`<option ${c===l?.currency?'selected':''}>${c}</option>`).join('')}</select>`)}</div>${note(duplicate?'A separate copy. Currency amounts are copied as entered, not converted. Review prices before assigning agents.':'Currency is fixed after creation. Assign prices before using this list.')}<div class="form-actions">${btn('Cancel','','data-close')}<button type="submit" class="btn primary">${icon('check')}${id&&!duplicate?'Save details':'Create list'}</button></div></form>`);}
    function assignModal(i){openModal('Regional prices · '+esc(agents[i].name),`<form id="su-assign-form" data-account="${i}">${field('Price list','su-assign-list',`<select id="su-assign-list">${S.lists.filter(l=>!l.archived).map(l=>`<option value="${l.id}" ${S.assigned[i]===l.id?'selected':''}>${esc(l.name)} · ${l.currency}</option>`).join('')}</select>`)}${note('Applies to future stock. This account’s received lots keep their prices and currency.')}<div class="form-actions">${btn('Cancel','','data-close')}<button class="btn primary" type="submit">Assign list</button></div></form>`);}
    function regionalPreview(i){const l=listFor(i);openModal('New stock price preview',`<div class="su-inline"><strong class="grow">${esc(agents[i].name)}</strong>${badge(l.name+' · '+l.currency)}</div><div class="su-regional-lines">${products.slice(0,3).map(p=>`<section class="su-region-line">${productGlyph(p)}<div class="grow"><strong>${esc(p.name)}</strong><small>${esc(p.dose)}</small></div><div class="form-grid">${field('Quantity','su-region-q-'+p.id,input('su-region-q-'+p.id,1,`type="number" min="0" max="999" data-region-qty="${p.id}"`))}${field('Sell / unit ('+l.currency+')','su-region-price-'+p.id,input('su-region-price-'+p.id,(l.prices[p.id]/100).toFixed(2),'type="number" readonly'))}</div></section>`).join('')}</div><div id="su-regional-total" class="su-total"></div>${note('Future shipment defaults only. Existing stock is unchanged. Costs remain separate; this is not a currency conversion.')}<div class="form-actions">${btn('Done','','data-close','primary')}</div>`,true);regionalTotal(i);S.regionPreview=i;}
    function regionalTotal(i){const l=listFor(i);let n=0;for(const p of products.slice(0,3)){const q=Number($('#su-region-q-'+p.id)?.value||0);if(Number.isSafeInteger(q)&&q>=0)n+=q*l.prices[p.id];}if($('#su-regional-total'))$('#su-regional-total').innerHTML=`<span>Selling value · ${l.currency}</span><strong>${money(n,l.currency)}</strong>`;}
    function myShop(){const i=activeAccount(),a=agents[i],p=profile(i),l=listFor(i);return `<div class="su-heading"><div><h1>Your private stock shop</h1><p>A simple way for customers to request what you have.</p></div>${badge(p.active?'Open':'Paused',p.active?'green':'orange')}</div><div class="su-settings-grid"><section class="panel"><div class="panel-head"><h2>Share your shop</h2>${icon('store')}</div><div class="panel-body"><div class="su-link"><span>${esc(shopURL(i).replace(/^https?:\/\//,''))}</span>${ib('copy','copy-link','Copy shop link')}</div><div class="su-inline-actions">${control('Customer preview','external-link','preview','primary')}${control('Share link','share-2','share-link')}</div><div class="su-shop-stats"><div><strong>${queryStock(i).length}</strong><small>Available products</small></div><div><strong>${S.requests.filter(r=>r.account===i&&r.status==='New').length}</strong><small>New requests</small></div></div>${control('Customer requests','inbox','requests')}</div></section><section class="panel"><div class="panel-head"><h2>Shop settings</h2>${icon('sliders-horizontal')}</div><form id="su-shop-form" class="panel-body"><div class="form-grid">${field('Shop name','su-shop-name',input('su-shop-name',p.name,'required maxlength="60"'))}${field('Access code','su-shop-pin',input('su-shop-pin',p.pin,'type="password" required minlength="4" maxlength="32" autocomplete="new-password"'))}</div><label class="su-check"><input type="checkbox" id="su-shop-qty" ${p.showQty?'checked':''}> Show exact available quantities</label><p class="su-helper">A shared code can be forwarded. Change it to reset access in this preview.</p><div class="su-inline-actions"><button type="submit" class="btn primary">Save settings</button>${control(p.active?'Pause shop':'Reopen shop',p.active?'pause':'play','pause')}</div></form></section><section class="panel"><div class="panel-head"><h2>Prices & access</h2>${icon('lock-keyhole')}</div><div class="panel-body">${keyRows([['Assigned price list',esc(l.name)+' · '+l.currency],['Current sample stock','EUR · saved batch prices'],['Payments','Arranged directly with you']])}${note('Customers see selling prices and availability. Costs, commissions and admin messages stay private.')}</div></section><section class="panel"><div class="panel-head"><h2>Customer experience</h2></div><div class="panel-body su-steps"><div><span>1</span><p>Browse your stock and send a request.</p></div><div><span>2</span><p>Review items, arrange payment and confirm the sale.</p></div><div><span>3</span><p>Share protocols and stay in touch in customer chat.</p></div></div></section></div><p class="su-design-note">Interface preview · sample data resets on reload. No public shop, security or payment service is connected.</p>`;}
    function requestList(){const rows=S.requests.filter(r=>r.account===activeAccount()&&(S.filter==='all'||r.status===S.filter)&&[r.id,r.name,r.email].join(' ').toLowerCase().includes(S.query.toLowerCase()));return inboxTabs('requests')+`<section class="panel"><div class="su-request-toolbar"><div class="search">${icon('search')}<input id="su-request-search" type="search" placeholder="Search requests or customers…" aria-label="Search customer requests" value="${esc(S.query)}"></div><select id="su-request-filter" aria-label="Request status">${['all','New','Reviewing','Awaiting payment','Converted','Declined','Cancelled'].map(s=>`<option value="${s}" ${S.filter===s?'selected':''}>${s==='all'?'All statuses':s}</option>`).join('')}</select></div><div class="su-request-head"><span>Request / customer</span><span>Items</span><span>Total</span><span>Status</span></div>${rows.map(r=>{const q=lineSummary(r);return `<button class="su-request-row" data-shop-action="request:${r.id}"><div><strong>${r.id}</strong><small>${esc(r.name)} · ${r.date}</small></div><span>${r.lines.reduce((n,l)=>n+l.q,0)} items</span><strong>${q?money(q.total):'Stock changed'}</strong>${badge(r.status,statusColor(r.status))}${icon('chevron-right')}</button>`;}).join('')||empty('No customer requests here.')}</section><p class="su-design-note">Requests do not reserve stock or count as sales until you confirm collection.</p>`;}
    function requestDetail(){const r=currentRequest();if(!r||r.account!==activeAccount())return empty('Choose one of your customer requests.');const q=r.booked||lineSummary(r),locked=['Converted','Declined','Cancelled'].includes(r.status);return `<div class="su-heading">${control('Requests','arrow-left','requests')}<div class="su-inline-actions">${control('Message','message-circle','request-chat:'+r.id)}${!locked?control('Edit request','pencil','edit-request:'+r.id):''}</div></div><section class="panel"><div class="panel-head"><div><small>${r.id} · ${r.date}</small><h1>${esc(r.name)}</h1></div>${badge(r.status,statusColor(r.status))}</div><div class="panel-body su-line-list">${r.lines.map((l,j)=>`<article>${productGlyph(products[l.product])}<div class="grow"><strong>${esc(products[l.product].name)}</strong><small>${esc(products[l.product].dose)} · Qty ${l.q}</small>${l.kind==='gift'?badge('Free extra'):l.kind==='discount'?badge('Discount'):''}${l.reason?`<small>${esc(l.reason)}</small>`:''}</div><strong>${q?money(q.rows.filter(a=>a.lineIndex===j).reduce((n,a)=>n+a.priceCents*a.q,0)):'—'}</strong></article>`).join('')}</div></section><div class="su-settings-grid mt"><section class="panel"><div class="panel-head"><h2>Customer details</h2></div><div class="panel-body">${keyRows([['Email',esc(r.email)],['Phone',esc(r.phone)],['Method',esc(r.delivery)],['Address',esc(r.address)],['Payment preference',esc(r.payment)]])}<p class="su-customer-note">${esc(r.note||'No customer note.')}</p></div></section><section class="panel"><div class="panel-head"><h2>Sale summary</h2></div><div class="panel-body">${q?keyRows([['Order total',money(q.total)],['Commission you keep',money(q.commission)],['Amount to business',money(q.total-q.commission)]]):note('Stock has changed. Edit and re-quote this request.','triangle-alert')}${!locked?`<div class="su-inline-actions mt">${control('Confirm sale','check','confirm:'+r.id,'primary')}${control('Await payment','clock-3','await:'+r.id)}${control('Decline','x','decline:'+r.id)}</div>${note('Confirm only after receiving payment. A payment preference is not proof of collection.')}`:r.status==='Converted'?control('Open order','arrow-up-right','converted:'+r.id,'primary mt'):''}</div></section></div>`;}
    function requestEditor(r){if(!canManage()||r.status==='Converted')return;S.editDraft=r.lines.map(l=>({...l}));S.editCustomer={name:r.name,email:r.email,phone:r.phone,address:r.address,note:r.note};paintRequestEditor(r);}
    function paintRequestEditor(r){openModal('Edit '+r.id,`<form id="su-request-edit"><div class="su-edit-lines">${S.editDraft.map((l,j)=>`<section><div class="su-inline">${productGlyph(products[l.product])}<strong class="grow">Item ${j+1}</strong>${ib('trash-2','remove-line:'+j,'Remove item '+(j+1))}</div><div class="form-grid">${field('Product','su-edit-product-'+j,`<select data-edit-product="${j}" id="su-edit-product-${j}">${queryStock(r.account).map(p=>`<option value="${p.id}" ${l.product===p.id?'selected':''}>${esc(p.name+' · '+p.dose)}</option>`).join('')}</select>`)}${field('Quantity','su-edit-qty-'+j,input('su-edit-qty-'+j,l.q,`type="number" min="1" max="999" required data-edit-qty="${j}"`))}${field('Adjustment','su-edit-kind-'+j,`<select id="su-edit-kind-${j}" data-edit-kind="${j}"><option value="normal" ${!l.kind||l.kind==='normal'?'selected':''}>Original price</option><option value="discount" ${l.kind==='discount'?'selected':''}>Discount</option><option value="gift" ${l.kind==='gift'?'selected':''}>Free extra</option></select>`)}${l.kind==='discount'?field('Discount / unit (€)','su-edit-discount-'+j,input('su-edit-discount-'+j,(l.discount||0)/100,`type="number" min="0.01" step="0.01" required data-edit-discount="${j}"`)):''}</div>${l.kind&&l.kind!=='normal'?field('Reason','su-edit-reason-'+j,`<input id="su-edit-reason-${j}" data-edit-reason="${j}" value="${esc(l.reason||'')}" placeholder="Why was this adjustment made?" required maxlength="250">`):''}</section>`).join('')}</div>${control('Add product or gift','plus','add-line','mt')}<div class="su-edit-contact"><h3>Customer details</h3><div class="form-grid">${field('Full name','su-edit-name',input('su-edit-name',S.editCustomer.name,'required maxlength="100" data-edit-customer="name"'))}${field('Email','su-edit-email',input('su-edit-email',S.editCustomer.email,'required type="email" maxlength="254" data-edit-customer="email"'))}${field('Phone','su-edit-phone',input('su-edit-phone',S.editCustomer.phone,'required type="tel" maxlength="40" data-edit-customer="phone"'))}${field('Address or pickup','su-edit-address',input('su-edit-address',S.editCustomer.address,'required maxlength="400" data-edit-customer="address"'))}</div>${field('Note','su-edit-note',`<textarea id="su-edit-note" data-edit-customer="note" maxlength="1000">${esc(S.editCustomer.note)}</textarea>`)}</div><div id="su-edit-error" class="su-error" role="alert"></div><div class="form-actions">${btn('Cancel','','data-close')}<button class="btn primary" type="submit">Save request</button></div></form>`,true);}
    function confirmModal(r){const q=lineSummary(r);if(!canManage()||!q||r.status==='Converted')return toast('Review this request and current stock first.');openModal('Confirm sale',`<div class="su-confirm-amount"><small>${r.id} · ${esc(r.name)}</small><strong>${money(q.total)}</strong></div>${keyRows([['Units leaving stock',String(q.units)],['Commission you keep',money(q.commission)],['Amount to business',money(q.total-q.commission)]])}<form id="su-convert"><label class="su-check"><input id="su-collected" type="checkbox" required> I received ${money(q.total)} from the customer.</label>${q.total!==r.originalTotal?`<label class="su-check"><input type="checkbox" required> The customer agreed to the changed basket and total.</label>`:''}<p class="su-helper">Records a sale in this design tab. No payment is processed.</p><div class="form-actions">${btn('Cancel','','data-close')}<button class="btn primary" type="submit">${icon('check')}Confirm sale</button></div></form>`);}
    function convert(r){if(!canManage()||r.status==='Converted')return;const q=lineSummary(r);if(!q)return toast('Stock changed. Review the basket.');const d=progressData(r.account),id='ORD-'+(r.account+1)+'-SHOP-'+String(d.serial++).padStart(4,'0'),seq=Date.now();q.rows.forEach((l,j)=>{const lot=priceLots(r.account).find(a=>a.id===l.lotId);lot.qty-=l.q;d.quantities[l.product]-=l.q;d.sales.unshift({id:id+'-'+j,orderId:id,product:l.product,q:l.q,price:l.priceCents/100,originalPrice:l.originalCents/100,cost:l.cost,lotId:l.lotId,source:l.source,commissionCents:l.commission,date:reportingToday,paid:true,settled:false,orderSequence:seq,customerName:r.name,customerContact:r.email,note:r.note,adjustment:l.kind==='normal'?'none':l.kind,adjustmentReason:l.reason,createdAt:new Date().toISOString()});});r.status='Converted';r.orderId=id;r.booked=q;closeModal();render();toast('Sale recorded in this preview','success');}
    function customerList(){const all=S.customers.filter(c=>c.account===activeAccount()&&(c.name+' '+c.email).toLowerCase().includes(S.chatQuery.toLowerCase()));return `<div class="su-tabs"><button data-page="messages">Admin</button><button class="active">Customers ${badge(all.filter(c=>c.unread).length)}</button></div><section class="panel su-customer-inbox"><div class="search">${icon('search')}<input id="su-chat-search" type="search" value="${esc(S.chatQuery)}" placeholder="Search customers…" aria-label="Search customer chats"></div>${all.slice(0,S.visible).map(c=>`<button class="su-client-row" data-shop-action="chat:${c.id}">${person(c.name)}<div class="grow"><strong>${esc(c.name)}</strong><small>${esc(c.messages.at(-1)?.text||'File attached')}</small></div>${c.unread?badge(c.unread):icon('chevron-right')}</button>`).join('')||empty('No customer conversations.')}<div id="su-chat-more">${all.length>S.visible?control('Load 20 more','arrow-down','more-chats','full'):''}</div></section>`;}
    function customerChat(publicView=false){const c=S.customers.find(c=>c.id===S.chat);if(!c)return publicView?customerContactForm():empty('Choose a conversation.');if(!publicView&&c.account!==activeAccount())return empty('Choose a conversation.');if(publicView&&(!S.customerContact||S.customerContact.chat!==c.id))return customerContactForm();const side=publicView?'customer':'agent',draft=S.messageDrafts.get(c.id+side)||'';return `<section class="su-chat"><header><button class="icon-btn" data-shop-action="${publicView?'back-shop':'customers'}" aria-label="Back">${icon('arrow-left')}</button><div><strong>${esc(publicView?agents[c.account].name:c.name)}</strong><small>${publicView?'Your agent':'Customer'}</small></div>${!publicView?ib('book-open','chat-protocols','Share a protocol'):''}</header><div id="su-chat-log" role="log" aria-label="Conversation history">${c.messages.length>20?control('Load earlier messages','history','earlier-messages','small'):''}${c.messages.slice(-(c.visible||20)).map(m=>`<article class="su-bubble ${m.by===side?'own':''}">${m.reply?`<small>${esc(m.reply)}</small>`:''}${m.file?.type.startsWith('image/')?`<img class="su-chat-image" src="${esc(m.file.url)}" alt="Image attachment" loading="lazy">`:''}${m.file?`<a download="${esc(m.file.name)}" href="${esc(m.file.url)}">${icon(m.file.type.startsWith('image/')?'image':'file-text')}${esc(m.file.name)}</a>`:''}${m.text?`<p>${esc(m.text)}</p>`:''}<time>${esc(m.at)}</time></article>`).join('')}</div><form id="su-chat-form" data-side="${side}"><div id="su-chat-attachment">${S.attachment?`<span>${icon('paperclip')}${esc(S.attachment.name)}${ib('x','remove-attachment','Remove attachment')}</span>`:''}</div><div class="su-compose"><label class="icon-btn" aria-label="Attach image or file" title="Attach image or file">${icon('plus')}<input id="su-chat-file" type="file" accept="image/*,.pdf,.txt" hidden></label><textarea id="su-chat-text" rows="1" placeholder="Message…" aria-label="Message" maxlength="2000">${esc(draft)}</textarea><button class="icon-btn" type="submit" aria-label="Send message" ${!draft.trim()&&!S.attachment?'disabled':''}>${icon('send')}</button></div><small class="su-design-note">Design preview · messages stay in this tab.</small></form></section>`;}
    function mountMore(){S.moreObserver?.disconnect();const el=$('#su-chat-more button');if(!el||!('IntersectionObserver' in window))return;S.moreObserver=new IntersectionObserver(entries=>{if(entries.some(x=>x.isIntersecting)){S.moreObserver.disconnect();const y=scrollY;S.visible+=20;render();window.scrollTo({top:y,behavior:'instant'});}},{rootMargin:'80px'});S.moreObserver.observe(el);}
    function mountChat(){const log=$('#su-chat-log');if(log)log.scrollTop=log.scrollHeight;fitChat();}
    function fitChat(){const c=$('.su-chat');if(!c||innerWidth>700)return;const vv=window.visualViewport,visible=vv?.height||innerHeight;document.body.classList.toggle('su-keyboard-open',innerHeight-visible>140);c.style.height=Math.max(240,visible+(vv?.offsetTop||0)-c.getBoundingClientRect().top-12)+'px';}
    window.visualViewport?.addEventListener('resize',fitChat);window.visualViewport?.addEventListener('scroll',fitChat);window.addEventListener('resize',fitChat);
    function hydrateCheckout(){if(state.page!=='checkout')return;for(const [id,value] of Object.entries(S.checkoutDraft)){const el=$('#'+id);if(el)el.value=value;}const pickup=$('#su-delivery')?.value==='Pickup';if($('#su-address-fields'))$('#su-address-fields').hidden=pickup;['su-address','su-city','su-country'].forEach(id=>{if($('#'+id))$('#'+id).required=!pickup;});if($('#su-other-wrap'))$('#su-other-wrap').hidden=$('#su-payment').value!=='Other';if($('#su-other'))$('#su-other').required=$('#su-payment').value==='Other';}
    function savePriceDraft(){const l=S.lists.find(x=>x.id===S.list),draft=S.priceDrafts[l.id]||{};if(l.archived)return;if(Object.values(draft).some(v=>cents(v)===null||cents(v)<=0||cents(v)>100000000)){toast('Enter a valid positive price with up to two decimals.');return;}for(const [id,value] of Object.entries(draft))l.prices[+id]=cents(value);delete S.priceDrafts[l.id];toast('Future stock prices saved in this preview','success');}

    function customerContactForm(){return `<section class="panel su-contact"><div class="panel-head"><div><h1>Message ${esc(agents[S.publicAccount]?.short||'your agent')}</h1><small>A private conversation about your request.</small></div></div><form id="su-contact-form" class="panel-body">${field('Full name','su-contact-name',input('su-contact-name','','required maxlength="100" autocomplete="name"'))}${field('Email','su-contact-email',input('su-contact-email','','required type="email" maxlength="254" autocomplete="email"'))}${field('Message','su-contact-message','<textarea id="su-contact-message" required maxlength="2000" placeholder="How can I help?"></textarea>')}<button class="btn primary full" type="submit">Send message</button></form></section>`;}
    function publicHeader(){return `<header class="su-store-header"><a href="#shop" class="su-store-brand"><span class="su-glyph">${icon('dna')}</span><span>PeptiStock<small>${esc(profile(S.publicAccount).name)}</small></span></a><div>${ib('message-circle','contact-agent','Message your agent')}${ib('shopping-bag','basket','Open basket')}<span class="su-cart-count">${Object.values(S.cart).reduce((n,q)=>n+q,0)}</span></div></header>`;}
    function renderPublic(){const i=S.publicAccount;if(!agents[i]){S.publicAccount=0;}$('#preview-toolbar').innerHTML='';document.title=profile(S.publicAccount).name+' · PeptiStock';let content='';const p=profile(S.publicAccount),status=agentMeta(S.publicAccount).status;
      if(!p.active||status!=='Active')content=`<section class="panel su-gate">${icon('store')}<h1>This shop is paused</h1><p>Please contact your agent directly.</p></section>`;
      else if(S.unlocked.get(S.publicAccount)!==p.epoch)content=gate();
      else if(state.page==='checkout')content=checkout();
      else if(state.page==='shop-confirmation')content=confirmation();
      else if(state.page==='shop-chat')content=customerChat(true);
      else content=storefront();
      $('#app').innerHTML=`<div class="su-store"><div class="su-preview-bar"><span>Customer view · design preview</span>${control('Back to workspace','arrow-left','workspace','small')}</div>${state.page==='shop-chat'&&S.customerContact?'':publicHeader()}<main>${content}</main><footer>Sample data only · no real orders, emails or messages are sent.</footer></div>`;icons();motionMount();mountChat();hydrateCheckout();}
    function gate(){return `<section class="panel su-gate"><span class="su-glyph">${icon('lock-keyhole')}</span><h1>Your agent’s private stock</h1><p>Enter the access code your agent shared with you.</p><form id="su-unlock">${field('Access code','su-access-code',input('su-access-code','','type="password" required minlength="4" maxlength="32" autocomplete="off"'))}<p id="su-pin-error" class="su-error" role="alert"></p><button type="submit" class="btn primary full">Open shop ${icon('arrow-right')}</button></form><small class="su-helper">Preview code: 2468. This screen demonstrates access; it is not a real security gate.</small></section>`;}
    function storefront(){const rows=queryStock(S.publicAccount).filter(p=>(p.name+' '+p.dose).toLowerCase().includes(S.shopSearch.toLowerCase())&&(S.category==='all'||categoryFor(p).id===S.category));return `<div class="su-store-intro"><span class="su-eyebrow">AVAILABLE FROM ${esc(agents[S.publicAccount].short.toUpperCase())}</span><h1>Find what you’re looking for.</h1><p>Browse available stock. Your agent will confirm your request.</p></div><div class="su-store-tools"><div class="search">${icon('search')}<input id="su-store-search" type="search" placeholder="Search products…" aria-label="Search shop products" value="${esc(S.shopSearch)}"></div><select id="su-category" aria-label="Product category"><option value="all">All categories</option>${productCategories.map(c=>`<option value="${c.id}" ${S.category===c.id?'selected':''}>${esc(c.label)}</option>`).join('')}</select></div><div class="su-store-grid">${rows.map(p=>`<article class="panel su-product"><div class="su-inline">${productGlyph(p)}${badge(profile(S.publicAccount).showQty?p.qty+' available':'In stock','green')}</div><h2>${esc(p.name)}</h2><small>${esc(p.dose)}</small><p>${esc(categoryFor(p).label)} · View product details and available documents.</p><div class="su-product-bottom"><div><strong>${money(Math.round(p.price*100))}</strong><small>${p.priceMin!==p.priceMax?'From · batch prices apply':'per unit'}</small></div><div class="su-stepper">${ib('minus','cart-remove:'+p.id,'Remove '+p.name)}<span>${S.cart[p.id]||0}</span>${ib('plus','cart-add:'+p.id,'Add '+p.name)}</div></div>${control('Details','arrow-up-right','product:'+p.id,'small su-product-more')}</article>`).join('')||empty('No available products match your search.')}</div>${Object.values(S.cart).some(Boolean)?`<div class="su-store-basket"><div><small>${Object.values(S.cart).reduce((n,q)=>n+q,0)} items</small><strong>${money(cartQuote()?.total||0)}</strong></div>${control('Review basket','shopping-bag','basket','primary')}</div>`:''}`;}
    const cartLines=()=>Object.entries(S.cart).filter(([id,q])=>q>0).map(([id,q])=>({product:+id,q}));
    const cartQuote=()=>quote(cartLines(),S.publicAccount);
    function basket(){const q=cartQuote();openModal('Your basket',q&&q.units?`<div class="su-line-list">${cartLines().map(l=>`<article>${productGlyph(products[l.product])}<div class="grow"><strong>${esc(products[l.product].name)}</strong><small>${esc(products[l.product].dose)}</small></div><div class="su-stepper">${ib('minus','basket-remove:'+l.product,'Remove unit')}<span>${l.q}</span>${ib('plus','basket-add:'+l.product,'Add unit')}</div></article>`).join('')}</div><div class="su-total"><span>Total</span><strong>${money(q.total)}</strong></div>${note('Availability and saved batch prices are checked again when your agent confirms.')}<div class="form-actions">${btn('Keep browsing','','data-close')}${control('Continue','arrow-right','checkout','primary')}</div>`:empty('Your basket is empty.'));}
    function checkout(){const q=cartQuote();if(!q?.units)return empty('Your basket is empty.');return `<div class="su-heading">${control('Back to stock','arrow-left','back-shop')}</div><div class="su-checkout-grid"><section class="panel"><div class="panel-head"><h1>Your details</h1></div><form id="su-checkout" class="panel-body"><div class="form-grid">${field('Full name','su-name',input('su-name','','required maxlength="100" autocomplete="name"'))}${field('Email','su-email',input('su-email','','required type="email" maxlength="254" autocomplete="email"'))}${field('Phone','su-phone',input('su-phone','','required type="tel" maxlength="40" autocomplete="tel"'))}${field('Receive your items','su-delivery','<select id="su-delivery"><option>Delivery</option><option>Pickup</option></select>')}</div><div id="su-address-fields"><div class="form-grid">${field('Address','su-address',input('su-address','','required maxlength="200" autocomplete="street-address"'))}${field('City','su-city',input('su-city','','required maxlength="80" autocomplete="address-level2"'))}${field('Postal code','su-postcode',input('su-postcode','','maxlength="20" autocomplete="postal-code"'))}${field('Country','su-country',input('su-country','','required maxlength="80" autocomplete="country-name"'))}</div></div>${field('Preferred payment method','su-payment','<select id="su-payment"><option>Cash</option><option>PayPal</option><option>Revolut</option><option>Wise</option><option>Other</option></select>')}<div id="su-other-wrap" hidden>${field('Payment method','su-other',input('su-other','','maxlength="80" placeholder="How would you prefer to pay?"'))}</div>${field('Note (optional)','su-checkout-note','<textarea id="su-checkout-note" maxlength="1000" placeholder="Anything your agent should know?"></textarea>')}${note('No payment is taken here. Arrange payment directly with your agent.','wallet')}<button class="btn primary full" type="submit">Send request ${icon('arrow-right')}</button></form></section><section class="panel su-checkout-summary"><div class="panel-head"><h2>Your request</h2>${control('Edit','pencil','basket','small')}</div><div class="panel-body su-line-list">${q.rows.map(l=>`<article><div class="grow"><strong>${esc(products[l.product].name)}</strong><small>${esc(products[l.product].dose)} · ${l.q} × ${money(l.priceCents)}</small></div><strong>${money(l.priceCents*l.q)}</strong></article>`).join('')}<div class="su-total"><span>Items total</span><strong>${money(q.total)}</strong></div><small class="su-helper">Any delivery arrangements are confirmed directly with your agent.</small></div></section></div>`;}
    function confirmation(){const r=S.requests.find(r=>r.id===S.last);if(!r||r.account!==S.publicAccount||S.customerContact?.chat!==r.chatId)return empty('No request submitted in this customer session.');return `<section class="panel su-gate su-success"><span class="su-success-mark">${icon('check')}</span><small>${r.id}</small><h1>${r.status==='Converted'?'Sale confirmed.':'Request received.'}</h1>${badge(r.status,statusColor(r.status))}<p>${r.status==='Converted'?'Your agent confirmed this sale. Message them about collection or delivery.':esc(agents[r.account].short)+' will review your items and arrange payment with you.'}</p><div class="su-confirm-amount"><strong>${money(r.originalTotal)}</strong><small>${r.lines.reduce((n,l)=>n+l.q,0)} items · ${esc(r.payment)} preferred</small></div>${control('Message your agent','message-circle','contact-agent','primary full')}${control('Continue browsing','arrow-left','back-shop','full mt')}</section>`;}
    function protocolBundle(o){const ids=[...new Set(o.lines.map(l=>l.product))];return ids.map(id=>({id,product:products[id],record:protocolRecords().get(id)}));}
    function protocolModal(key,share=false){const o=orderFromKey(key);if(!o||workflow.support)return;S.protocolOrder=key;S.protocolShare=share;const bundle=protocolBundle(o),available=bundle.filter(x=>x.record?.current);openModal(share?'Share order protocols':'Email order protocols',`<div class="su-protocol-order"><strong>${esc(o.id)}</strong><small>${esc(o.customerName||'Customer')}</small></div><form id="su-protocol-form">${!share?field('Send to','su-protocol-email',input('su-protocol-email',o.customerContact?.includes('@')?o.customerContact:'','type="email" required maxlength="254" placeholder="customer@example.com"')):''}<div class="su-protocol-list">${bundle.map(x=>`<label class="su-protocol-row">${x.record?.current?`<input type="checkbox" name="protocol" value="${x.id}" checked>`:icon('file-x')}<span class="su-glyph">${icon('file-text')}</span><span class="grow"><strong>${esc(x.product.name)}</strong><small>${esc(x.product.dose)} · ${x.record?.current?'PDF · version '+x.record.revision:'No approved PDF available'}</small></span>${badge(x.record?.current?'Available':'Missing',x.record?.current?'green':'orange')}</label>`).join('')}</div>${available.some(x=>x.record.current.batch!=='All batches')?`<label class="su-check"><input id="su-protocol-batch" type="checkbox" required> I checked the batch applicability of the selected documents.</label>`:''}${note(share?'Your phone chooses the available sharing apps. These sample files contain no usage instructions.':'Prepare a branded email preview. No real email will be sent.')}<div class="form-actions">${btn('Cancel','','data-close')}<button class="btn primary" type="submit" ${!available.length?'disabled':''}>${icon(share?'share-2':'mail')}${share?'Share selected PDFs':'Preview email'}</button></div></form>${S.emailHistory.filter(h=>h.key===key).map(h=>`<p class="su-helper">${esc(h.text)}</p>`).join('')}`,true);}
    async function selectedProtocols(form){const selected=[...form.querySelectorAll('input[name="protocol"]:checked')].map(n=>Number(n.value));if(!selected.length){toast('Select at least one protocol.');return;}if(selected.some(id=>!protocolRecords().get(id)?.current)){toast('A selected protocol changed. Reopen the document list.');return;}const files=selected.map(id=>{const r=protocolRecords().get(id);return new File([protocolFile(r)],products[id].name.replace(/[^a-z0-9-]/gi,'-')+'-'+products[id].dose.replace(/\W/g,'')+'-v'+r.revision+'.pdf',{type:'application/pdf'});});if(S.protocolShare){if(navigator.canShare?.({files})&&navigator.share){try{await navigator.share({files,title:'Order protocols'});S.emailHistory.push({key:S.protocolOrder,text:'Files handed to the device share sheet'});closeModal();}catch(err){if(err.name!=='AbortError')shareFallback(files);}return;}shareFallback(files);return;}
      const email=$('#su-protocol-email').value,order=orderFromKey(S.protocolOrder);S.emailHistory.push({key:S.protocolOrder,text:'Email preview prepared for '+email+' · '+files.length+' PDFs · not sent'});openModal('Email preview',`<div class="su-email-envelope"><span>TO <strong>${esc(email)}</strong></span><span>SUBJECT <strong>Your protocols · ${esc(order.id)}</strong></span></div><article class="su-email-preview"><div class="su-email-brand">${icon('dna')}PeptiStock</div><h2>Your documents, together.</h2><p>Hello ${esc(order.customerName||'there')},</p><p>Here are the uploaded protocol documents for your order. Contact your agent if a document is missing or does not match your item.</p><div class="su-email-files">${files.map(f=>`<div>${icon('file-text')}<span>${esc(f.name)}</span></div>`).join('')}</div><p class="muted">${esc(agents[order.index].name)} · Your PeptiStock contact</p></article>${note('Design preview only. No email was queued or sent.','circle-check')}<div class="form-actions">${btn('Close','','data-close','primary')}</div>`,true);}
    function shareFallback(files){openModal('Download to share',`<p>Your browser cannot share these files together. Download them, then attach them in your preferred app.</p><div class="su-downloads">${files.map((f,i)=>{const url=URL.createObjectURL(f);return `<a class="btn" download="${esc(f.name)}" href="${url}">${icon('download')}${esc(f.name)}</a>`;}).join('')}</div>${note('Sample PDFs only. No customer recipient is selected automatically.')}`);}
    function chatProtocols(){const list=[...protocolRecords().values()].filter(r=>r.current);openModal('Share a protocol',`<div class="su-downloads">${list.map(r=>control(products[r.product].name+' · '+products[r.product].dose,'file-text','attach-protocol:'+r.product)).join('')}</div>${note('Only the selected document is added to this customer conversation.')}`);}
    function onAction(action){const [a,...rest]=action.split(':'),id=rest.join(':');
      if(a==='lists')go('price-lists');if(a==='list'){S.list=id;S.listSearch='';go('price-list');}
      if(a==='new-list')listModal();if(a==='duplicate')listModal(id,true);if(a==='rename')listModal(id);
      if(a==='save-prices')savePriceDraft();
      if(a==='archive'){const l=S.lists.find(x=>x.id===id);if(!l.archived&&S.assigned.includes(id))return toast('Reassign its agents before archiving this list.');l.archived=!l.archived;render();}
      if(a==='region-preview')regionalPreview(+id);if(a==='assign')assignModal(+id);if(a==='copy-link')navigator.clipboard?.writeText(shopURL(activeAccount())).then(()=>toast('Shop preview link copied','success')).catch(()=>toast('Copy the link shown above.'));
      if(a==='share-link'){const url=shopURL(activeAccount());if(navigator.share)navigator.share({title:profile().name,url}).catch(()=>{});else navigator.clipboard?.writeText(url).then(()=>toast('Link copied','success'));}
      if(a==='preview'){S.publicAccount=activeAccount();S.unlocked.delete(S.publicAccount);S.cart={};go('shop');}
      if(a==='workspace'){state.role='agent';S.workspaceAccount=S.publicAccount;workflow.shop=isShopAccount(S.publicAccount);workflow.type=flowProfile(S.publicAccount);go('my-shop');}
      if(a==='pause'){profile().active=!profile().active;S.unlocked.delete(activeAccount());render();}
      if(a==='requests')go('customer-requests');if(a==='request'){S.selected=id;go('customer-request');}
      if(a==='edit-request')requestEditor(currentRequest());
      if(a==='add-line'){S.editDraft.push({product:queryStock(currentRequest().account)[0]?.id||0,q:1});paintRequestEditor(currentRequest());}
      if(a==='remove-line'){if(S.editDraft.length===1)return toast('Keep one item or decline the request.');S.editDraft.splice(+id,1);paintRequestEditor(currentRequest());}
      if(a==='confirm')confirmModal(currentRequest());if(a==='await'){currentRequest().status='Awaiting payment';render();toast('Awaiting customer payment','success');}
      if(a==='decline'){openModal('Decline request',`<form id="su-decline-form">${field('Reason','su-decline-reason','<textarea id="su-decline-reason" required maxlength="500" placeholder="Why is this request being declined?"></textarea>')}<div class="form-actions">${btn('Keep request','','data-close')}<button type="submit" class="btn danger">Decline request</button></div></form>`);}
      if(a==='converted'){const r=currentRequest();orderDetail(r.account,r.orderId);}
      if(a==='customers'){S.attachment=null;go('customers');}if(a==='chat'){S.chat=id;const c=S.customers.find(c=>c.id===id);if(c.account!==activeAccount())return;c.unread=0;S.attachment=null;go('customer-chat');}
      if(a==='request-chat'){const r=currentRequest();S.chat=r.chatId;go('customer-chat');}
      if(a==='more-chats'){S.visible+=20;render();}if(a==='earlier-messages'){const log=$('#su-chat-log'),height=log.scrollHeight,top=log.scrollTop;S.customers.find(c=>c.id===S.chat).visible=(S.customers.find(c=>c.id===S.chat).visible||20)+20;render();const next=$('#su-chat-log');next.scrollTop=next.scrollHeight-height+top;}
      if(a==='remove-attachment'){S.attachment=null;render();}if(a==='chat-protocols')chatProtocols();
      if(a==='attach-protocol'){const r=protocolRecords().get(+id);S.attachment={name:products[+id].name+'-v'+r.revision+'.pdf',type:'application/pdf',url:protocolURL(r)};closeModal();render();}
      if(['cart-add','basket-add','cart-remove','basket-remove'].includes(a)){const p=queryStock(S.publicAccount).find(p=>p.id===+id),q=(S.cart[id]||0)+(a.endsWith('add')?1:-1);if(!p||q>p.qty){toast('No more units are available.');return;}if(q<=0)delete S.cart[id];else S.cart[id]=q;if(a.startsWith('basket'))basket();else render();}
      if(a==='basket')basket();if(a==='checkout'){closeModal();go('checkout');}if(a==='back-shop')go('shop');
      if(a==='product'){const p=products[+id];openModal(esc(p.name),`<div class="su-product-detail">${productGlyph(p)}<h2>${esc(p.name)}</h2><small>${esc(p.dose)}</small><p>${esc(categoryFor(p).label)}</p>${note('Product information and documents are provided by your agent. This preview contains no usage instructions.')}<div class="form-actions">${btn('Close','','data-close')}${control('Message agent','message-circle','contact-agent','primary')}</div></div>`);}
      if(a==='contact-agent'){closeModal();if(S.customerContact?.account===S.publicAccount)S.chat=S.customerContact.chat;else S.chat=null;go('shop-chat');}
      if(a==='protocol')protocolModal(id);if(a==='share')protocolModal(id,true);
    }
    document.addEventListener('click',e=>{const b=e.target.closest('[data-shop-action]');if(!b)return;e.preventDefault();if(workflow.support&&!['preview','copy-link','lists','requests','request','customers','chat'].includes(b.dataset.shopAction.split(':')[0])){toast('Read-only support view.');return;}onAction(b.dataset.shopAction);});
    function rerenderInput(id,fn){const el=$('#'+id),pos=el?.selectionStart;fn();render();const next=$('#'+id);next?.focus({preventScroll:true});if(pos!==null&&next?.setSelectionRange)next.setSelectionRange(pos,pos);}
    document.addEventListener('input',e=>{
      const n=e.target;if(n.dataset.regionQty!==undefined)regionalTotal(S.regionPreview);if(n.setCustomValidity)n.setCustomValidity('');if(n.dataset.editCustomer)S.editCustomer[n.dataset.editCustomer]=n.value;if(n.dataset.listPrice!==undefined){(S.priceDrafts[S.list]||=( {}))[n.dataset.listPrice]=n.value;}if(state.page==='checkout'&&n.id)S.checkoutDraft[n.id]=n.value;if(n.id==='su-list-search')rerenderInput(n.id,()=>S.listSearch=n.value);
      if(n.id==='su-store-search')rerenderInput(n.id,()=>S.shopSearch=n.value);
      if(n.id==='su-request-search')rerenderInput(n.id,()=>S.query=n.value);
      if(n.id==='su-chat-search')rerenderInput(n.id,()=>S.chatQuery=n.value);
      if(n.id==='su-chat-text'){const side=$('#su-chat-form').dataset.side;S.messageDrafts.set(S.chat+side,n.value);n.style.height='auto';n.style.height=Math.min(n.scrollHeight,120)+'px';$('#su-chat-form button[type="submit"]').disabled=!n.value.trim()&&!S.attachment;}
      for(const [key,prop] of [['editQty','q'],['editReason','reason'],['editDiscount','discount']])if(n.dataset[key]!==undefined){const row=S.editDraft[+n.dataset[key]];row[prop]=prop==='q'?Number(n.value):prop==='discount'?cents(n.value):n.value;}
    });
    document.addEventListener('change',e=>{if(e.target.id==='preview-account-type')delete S.workspaceAccount;},true);
    document.addEventListener('change',e=>{const n=e.target;if(state.page==='checkout'&&n.id)S.checkoutDraft[n.id]=n.value;if(n.id==='su-request-filter'){S.filter=n.value;render();}if(n.id==='su-category'){S.category=n.value;render();}
      if(n.dataset.editProduct!==undefined){S.editDraft[+n.dataset.editProduct].product=+n.value;paintRequestEditor(currentRequest());}
      if(n.dataset.editKind!==undefined){S.editDraft[+n.dataset.editKind].kind=n.value;paintRequestEditor(currentRequest());}
      if(n.id==='su-delivery'){$('#su-address-fields').hidden=n.value==='Pickup';['su-address','su-city','su-country'].forEach(id=>$('#'+id).required=n.value!=='Pickup');}
      if(n.id==='su-payment'){$('#su-other-wrap').hidden=n.value!=='Other';$('#su-other').required=n.value==='Other';}
      if(n.id==='su-chat-file'&&n.files[0]){const f=n.files[0];if(f.size>10*1024*1024||!(/^(image\/(png|jpeg|webp|gif)|application\/pdf|text\/plain)$/.test(f.type))){toast('Choose an image, PDF or text file up to 10 MB.');return;}S.attachment={name:f.name,type:f.type,url:URL.createObjectURL(f)};render();}
    });
    document.addEventListener('submit',e=>{const f=e.target;if(!f.id.startsWith('su-'))return;e.preventDefault();if(workflow.support){toast('Read-only support view.');return;}for(const n of f.querySelectorAll('input[required]:not([type=checkbox]):not([type=password]):not([type=number]),textarea[required]')){n.value=n.value.trim();n.setCustomValidity(n.value?'':'Please fill in this field.');}if(!f.reportValidity())return;
      if(f.id==='su-list-form'){const src=S.lists.find(l=>l.id===f.dataset.list),dup=f.dataset.duplicate==='true';if(src&&!dup){src.name=$('#su-list-name').value.trim();src.region=$('#su-list-region').value.trim();}else{const id='list-'+Date.now();S.lists.push({id,name:$('#su-list-name').value.trim(),region:$('#su-list-region').value.trim(),currency:$('#su-list-currency').value,prices:src?[...src.prices]:products.map(p=>Math.round(p.price*100))});S.list=id;}closeModal();go('price-list');toast('Price list saved in this preview','success');}
      if(f.id==='su-assign-form'){S.assigned[+f.dataset.account]=$('#su-assign-list').value;closeModal();render();toast('Future stock list assigned','success');}
      if(f.id==='su-shop-form'){const p=profile();p.name=$('#su-shop-name').value.trim();const pin=$('#su-shop-pin').value;if(pin!==p.pin){p.pin=pin;p.epoch++;S.unlocked.delete(activeAccount());}p.showQty=$('#su-shop-qty').checked;toast('Shop settings saved in this preview','success');}
      if(f.id==='su-request-edit'){const r=currentRequest(),q=quote(S.editDraft,r.account);if(!q){$('#su-edit-error').textContent='Check stock quantities and discounts against the saved batch prices.';return;}if(S.editDraft.some(l=>l.kind&&l.kind!=='normal'&&!l.reason?.trim())){$('#su-edit-error').textContent='Add a reason for every discount or free extra.';return;}r.lines=S.editDraft.map(l=>({...l}));Object.assign(r,S.editCustomer);r.status='Reviewing';closeModal();render();toast('Request updated','success');}
      if(f.id==='su-convert')convert(currentRequest());
      if(f.id==='su-decline-form'){currentRequest().status='Declined';currentRequest().declineReason=$('#su-decline-reason').value.trim();closeModal();render();toast('Request declined','success');}
      if(f.id==='su-unlock'){if($('#su-access-code').value!==profile(S.publicAccount).pin){$('#su-pin-error').textContent='That code does not match. Please try again.';return;}S.unlocked.set(S.publicAccount,profile(S.publicAccount).epoch);go('shop');}
      if(f.id==='su-checkout'){const q=cartQuote();if(!q?.units){toast('Stock changed. Review your basket.');return;}const pickup=$('#su-delivery').value==='Pickup',r={id:'CR-'+String(S.next++).padStart(4,'0'),account:S.publicAccount,name:$('#su-name').value.trim(),email:$('#su-email').value.trim(),phone:$('#su-phone').value.trim(),delivery:$('#su-delivery').value,address:pickup?'Pickup with agent':[$('#su-address').value,$('#su-city').value,$('#su-postcode').value,$('#su-country').value].map(s=>s.trim()).filter(Boolean).join(', '),payment:$('#su-payment').value==='Other'?$('#su-other').value.trim():$('#su-payment').value,note:$('#su-checkout-note').value.trim(),status:'New',date:reportingToday,lines:cartLines(),originalTotal:q.total};let c=S.customerContact?.account===r.account&&S.customers.find(c=>c.id===S.customerContact.chat&&c.email===r.email);if(c){c.messages.push({by:'customer',text:'I sent request '+r.id+'. '+(r.note||''),at:'Now'});c.unread++;}else c=createThread(r.account,r.name,r.email,'I sent request '+r.id+'. '+(r.note||''));r.chatId=c.id;S.customerContact={account:r.account,chat:c.id};S.requests.unshift(r);S.last=r.id;S.cart={};S.checkoutDraft={};go('shop-confirmation');}
      if(f.id==='su-contact-form'){const c=createThread(S.publicAccount,$('#su-contact-name').value.trim(),$('#su-contact-email').value.trim(),$('#su-contact-message').value.trim());S.chat=c.id;S.customerContact={account:S.publicAccount,chat:c.id};render();}
      if(f.id==='su-chat-form'){const c=S.customers.find(c=>c.id===S.chat),side=f.dataset.side,text=$('#su-chat-text').value.trim();if(!text&&!S.attachment)return;c.messages.push({by:side,text,file:S.attachment,at:new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit'}).format(new Date())});if(side==='customer')c.unread++;S.messageDrafts.set(c.id+side,'');S.attachment=null;render();}
      if(f.id==='su-protocol-form')selectedProtocols(f);
    });
    // Design-review entry points, without modifying existing production API pages.
    if(newRoutes.has(requestedPage)){state.page=requestedPage;history.replaceState(null,'','#'+requestedPage);}
    render();
  });
})();
